-- A executer dans Supabase > SQL Editor, en une seule fois (tout le script). Relancable sans doublon.
-- Couche MyMaps de la carte du CRM : les 867 dessins de l'ancienne carte MyMaps qui n'ont pas de terrain dans le CRM.
-- Ils restent hors du listing des terrains. Visible uniquement par les admins et les associes, en vue Interne.
-- Le bouton Creer le terrain de la carte appelle mymaps_lier_terrain : le dessin devient le contour du nouveau terrain
-- et sort de la couche. Rien n'est supprime, un dessin deja transforme en terrain n'est pas remis dans la couche.

create table if not exists public.mymaps_dessins (
  id integer primary key,
  nom text, note text, couleur text, zonage text,
  surface numeric,            -- surface ecrite dans le nom MyMaps
  surface_dessin numeric,     -- surface mesuree sur le dessin
  prix numeric,               -- prix au m2 lu dans la note
  tf_cadgis text,             -- titre de la parcelle CADGIS qui coincide avec le dessin
  lat double precision, lng double precision,
  geom jsonb not null, geom_approx jsonb not null,
  lat_approx double precision, lng_approx double precision,
  terrain_id bigint,          -- renseigne quand le dessin est devenu un terrain du CRM
  importe_le timestamptz not null default now()
);
alter table public.mymaps_dessins enable row level security;
drop policy if exists "mymaps_lecture" on public.mymaps_dessins;
create policy "mymaps_lecture" on public.mymaps_dessins for select to authenticated
  using (public.mon_role() in ('admin', 'associe'));
revoke all on public.mymaps_dessins from anon;
grant select on public.mymaps_dessins to authenticated;

-- Transforme un dessin en contour du terrain qui vient d'etre cree, et le sort de la couche
create or replace function public.mymaps_lier_terrain(p_dessin integer, p_terrain bigint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  d public.mymaps_dessins;
  r text;
begin
  if public.mon_role() is null or public.mon_role() not in ('admin', 'associe') then
    return jsonb_build_object('ok', false, 'raison', 'droits insuffisants');
  end if;
  select * into d from public.mymaps_dessins where id = p_dessin;
  if not found then return jsonb_build_object('ok', false, 'raison', 'dessin introuvable'); end if;
  if d.terrain_id is not null then return jsonb_build_object('ok', false, 'raison', 'dessin deja transforme en terrain'); end if;
  select ref into r from public.terrains where id = p_terrain;
  if r is null then return jsonb_build_object('ok', false, 'raison', 'terrain introuvable'); end if;
  insert into public.terrain_contours (cle, surface_plan, geom, geom_approx, lat, lng, lat_approx, lng_approx)
  values (r, d.surface_dessin, d.geom, d.geom_approx, d.lat, d.lng, d.lat_approx, d.lng_approx)
  on conflict (cle) do update set surface_plan = excluded.surface_plan, geom = excluded.geom, geom_approx = excluded.geom_approx,
    lat = excluded.lat, lng = excluded.lng, lat_approx = excluded.lat_approx, lng_approx = excluded.lng_approx, importe_le = now();
  update public.mymaps_dessins set terrain_id = p_terrain where id = p_dessin;
  return jsonb_build_object('ok', true, 'ref', r);
end;
$$;
revoke all on function public.mymaps_lier_terrain(integer, bigint) from public;
grant execute on function public.mymaps_lier_terrain(integer, bigint) to authenticated;

